[{"order":1,"type":"heading","text":"Local State Management: useState, useReducer, useContext, and Performance Pitfalls in React Native"},{"order":2,"type":"paragraph","text":"Effective state management is crucial for building performant React Native applications. While global state libraries have their place, mastering local state primitives like useState, useReducer, and useContext is fundamental for clean, maintainable, and fast mobile apps."},{"order":3,"type":"subheading","text":"1. useState: The Foundation of Local State"},{"order":4,"type":"paragraph","text":"The useState hook is your primary tool for managing simple, independent component-level states. In React Native, updating state triggers a re-render of the component. Keeping state as local as possible prevents unnecessary re-renders of parent components."},{"order":5,"type":"code","text":"import React, { useState } from 'react';
import { View, Text, Button, StyleSheet } from 'react-native';

const Counter = () => {
  const [count, setCount] = useState(0);

  return (
    <View style={styles.container}>
      <Text>Count: {count}</Text>
      <Button title="Increment" onPress={() => setCount(prev => prev + 1)} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: { padding: 20 }
});"},{"order":6,"type":"subheading","text":"2. useReducer: Managing Complex State Logic"},{"order":7,"type":"paragraph","text":"When your state logic involves multiple sub-values or when the next state depends heavily on the previous one, useReducer is often cleaner than useState. It centralizes state transitions inside a reducer function."},{"order":8,"type":"code","text":"import React, { useReducer } from 'react';
import { View, Text, Button } from 'react-native';

const initialState = { step: 0, values: {} };

const reducer = (state, action) => {
  switch (action.type) {
    case 'NEXT_STEP':
      return { ...state, step: state.step + 1 };
    case 'SET_VALUE':
      return { ...state, values: { ...state.values, [action.field]: action.payload } };
    default:
      throw new Error();
  }
};

const FormWizard = () => {
  const [state, dispatch] = useReducer(reducer, initialState);
  return (
    <View>
      <Text>Current Step: {state.step}</Text>
      <Button title="Next" onPress={() => dispatch({ type: 'NEXT_STEP' })} />
    </View>
  );
};"},{"order":9,"type":"subheading","text":"3. useContext: Avoiding Prop Drilling"},{"order":10,"type":"paragraph","text":"The Context API allows you to share data across the component tree without passing props manually at every level. Combined with useReducer, it can serve as a lightweight alternative to external state management libraries."},{"order":11,"type":"subheading","text":"4. Performance Pitfalls in React Native"},{"order":12,"type":"bullet_point","text":"Unnecessary Re-renders via Context: Every component consuming a context will re-render whenever *any* value in that context changes, even if the consumed slice did not change."},{"order":13,"type":"bullet_point","text":"Inline Object/Function Definitions: Passing inline objects or functions as context values breaks referential equality, forcing consumers to re-render on every parent render."},{"order":14,"type":"bullet_point","text":"Placing Global State at the Root: Putting rapidly changing UI state (like scroll coordinates) in a global context can freeze your React Native UI bridge."},{"order":15,"type":"subheading","text":"5. Mitigating Performance Issues"},{"order":16,"type":"paragraph","text":"To keep your React Native applications running at a smooth 60 or 120 FPS, memoize your context values using useMemo and wrap callback functions in useCallback. Furthermore, split large contexts into smaller, domain-specific contexts to limit the scope of re-renders."},{"order":17,"type":"code","text":"import React, { createContext, useMemo, useState } from 'react';

export const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);

  // Memoize the value object to prevent unnecessary downstream renders
  const value = useMemo(() => ({
    user,
    login: (userData) => setUser(userData),
    logout: () => setUser(null)
  }), [user]);

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};"}]
